-- Forward-only, additive schema. Existing public Supabase tables are untouched.
CREATE SCHEMA IF NOT EXISTS rethread;
SET search_path TO rethread, public;
CREATE TABLE tenants(id uuid PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id bigint PRIMARY KEY, login text NOT NULL, avatar_url text NOT NULL);
CREATE TABLE memberships(tenant_id uuid REFERENCES tenants(id),user_id bigint REFERENCES users(id),role text NOT NULL CHECK(role IN ('owner','member')),PRIMARY KEY(tenant_id,user_id));
CREATE TABLE sessions(id_hash text PRIMARY KEY,user_id bigint REFERENCES users(id),tenant_id uuid NOT NULL REFERENCES tenants(id),csrf text NOT NULL,token_cipher text NOT NULL,expires_at timestamptz NOT NULL,FOREIGN KEY(tenant_id,user_id) REFERENCES memberships(tenant_id,user_id));
CREATE TABLE oauth_states(id_hash text PRIMARY KEY,verifier text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE installations(tenant_id uuid REFERENCES tenants(id),id bigint,account text NOT NULL,connected boolean NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,id));
CREATE TABLE repositories(tenant_id uuid NOT NULL,id uuid NOT NULL,github_id bigint NOT NULL,installation_id bigint NOT NULL,full_name text NOT NULL,default_branch text NOT NULL,connected boolean NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,github_id),FOREIGN KEY(tenant_id,installation_id) REFERENCES installations(tenant_id,id));
CREATE TABLE cases(tenant_id uuid NOT NULL,id uuid NOT NULL,repository_id uuid NOT NULL,title text NOT NULL,state text NOT NULL CHECK(state IN ('queued','capturing','reproducing','diagnosing','proposing','verifying','ready_for_review','publishing','pr_opened','needs_input','unsupported','blocked','failed','cancelled','rejected','superseded')),base_sha text NOT NULL CHECK(base_sha ~ '^[a-f0-9]{40}$'),branch text NOT NULL,reason text,cursor bigint NOT NULL DEFAULT 0,data jsonb NOT NULL DEFAULT '{}',idempotency_key text NOT NULL,request_hash text NOT NULL,archived boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,idempotency_key),FOREIGN KEY(tenant_id,repository_id) REFERENCES repositories(tenant_id,id));
CREATE TABLE jobs(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,case_id uuid,repository_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('repair','publish','preflight')),payload jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','completed','failed','cancelled')),fence bigint NOT NULL DEFAULT 0,worker_id text,lease_until timestamptz,heartbeat_at timestamptz,attempts int NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),checkpoint jsonb NOT NULL DEFAULT '{}',sandbox_id text,reason text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,case_id) REFERENCES cases(tenant_id,id),FOREIGN KEY(tenant_id,repository_id) REFERENCES repositories(tenant_id,id));
CREATE INDEX jobs_claim ON jobs(next_attempt_at,created_at) WHERE status IN ('queued','running');
CREATE UNIQUE INDEX one_active_job_per_case ON jobs(tenant_id,case_id,kind) WHERE status IN ('queued','running');
CREATE TABLE events(tenant_id uuid NOT NULL,case_id uuid NOT NULL,sequence bigint NOT NULL,type text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,case_id,sequence),FOREIGN KEY(tenant_id,case_id) REFERENCES cases(tenant_id,id));
CREATE TABLE artifacts(tenant_id uuid NOT NULL,id uuid NOT NULL,case_id uuid NOT NULL,kind text NOT NULL,content_hash text NOT NULL,raw_bytes int NOT NULL CHECK(raw_bytes<=10485760),truncated boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '30 days',PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,id,case_id),FOREIGN KEY(tenant_id,case_id) REFERENCES cases(tenant_id,id));
CREATE TABLE artifact_payloads(tenant_id uuid NOT NULL,id uuid NOT NULL,case_id uuid NOT NULL,payload bytea NOT NULL,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,id,case_id) REFERENCES artifacts(tenant_id,id,case_id) ON DELETE CASCADE);
CREATE TABLE guards(tenant_id uuid NOT NULL,id uuid NOT NULL,repository_id uuid NOT NULL,case_id uuid NOT NULL,test_name text NOT NULL,path text NOT NULL,contract text NOT NULL,source_paths text[] NOT NULL,content text NOT NULL,validity text NOT NULL DEFAULT 'active' CHECK(validity IN ('active','stale','needs_review')),last_sha text,last_passed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,case_id),FOREIGN KEY(tenant_id,repository_id) REFERENCES repositories(tenant_id,id),FOREIGN KEY(tenant_id,case_id) REFERENCES cases(tenant_id,id));
CREATE TABLE guard_checks(tenant_id uuid NOT NULL,id uuid NOT NULL,guard_id uuid NOT NULL,job_id uuid REFERENCES jobs(id),head_sha text NOT NULL,passed boolean NOT NULL,selection_reason text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(job_id,guard_id),FOREIGN KEY(tenant_id,guard_id) REFERENCES guards(tenant_id,id));
CREATE TABLE webhook_deliveries(id text PRIMARY KEY,event text NOT NULL,payload_hash text NOT NULL,received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE publish_intents(tenant_id uuid NOT NULL,case_id uuid NOT NULL,idempotency_key text NOT NULL,digest text NOT NULL,branch text NOT NULL,commit_sha text,pr_url text,status text NOT NULL DEFAULT 'queued',reason text,PRIMARY KEY(tenant_id,case_id),UNIQUE(tenant_id,idempotency_key),FOREIGN KEY(tenant_id,case_id) REFERENCES cases(tenant_id,id));
CREATE TABLE budgets(scope text NOT NULL,day date NOT NULL,reserved_micros bigint NOT NULL DEFAULT 0,spent_micros bigint NOT NULL DEFAULT 0,ceiling_micros bigint NOT NULL CHECK(ceiling_micros>=0),PRIMARY KEY(scope,day),CHECK(reserved_micros>=0 AND spent_micros>=0 AND reserved_micros+spent_micros<=ceiling_micros));
CREATE TABLE budget_reservations(id text PRIMARY KEY,tenant_id uuid REFERENCES tenants(id),day date NOT NULL,amount_micros bigint NOT NULL,settled boolean NOT NULL DEFAULT false,actual_micros bigint);
CREATE TABLE audit_records(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id uuid REFERENCES tenants(id),user_id bigint REFERENCES users(id),action text NOT NULL,object_id text,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX cases_search ON cases USING gin(to_tsvector('english', title || ' ' || coalesce(data->'request'->>'behaviorContract','')));
CREATE TABLE worker_heartbeats(id text PRIMARY KEY,updated_at timestamptz NOT NULL DEFAULT now(),build_id text NOT NULL);
